function check(bool $ok,string $label):void{if(!$ok)throw new RuntimeException($label);}
function denied(callable $fn,int $status):void{try{$fn();}catch(HttpError $e){check($e->getCode()===$status,$e->getMessage());return;}throw new RuntimeException('İşlem reddedilmedi.');}
function fresh():Database{$db=new Database(['dsn'=>'sqlite::memory:']);$db->pdo->exec(file_get_contents(__DIR__.'/schema.sqlite.sql'));AdminMfaSchema::install($db);\Omnigo\AccountSettingsSchema::install($db);\Omnigo\ApplicationAdditiveSchema::ensure($db);\Omnigo\AccountDirectorySchema::ensure($db);return $db;}
$db=fresh();$password='Test-Only-Strong-Password-957!';$hash=Security::hashPassword($password);
$db->run("INSERT INTO companies VALUES(1,'Örnek')");
