$security=new Security($db,$config);$mfa=new AdminEmailMfa($db,$config);$store=new AdminMfaStore($db,$config);$mail=new MailQueue($db,$config);
$_SERVER['REMOTE_ADDR']='test';$raw=str_repeat('b',64);$old=hash('sha256',$raw);$db->run('INSERT INTO sessions VALUES(?,1,?,?)',[$old,'csrf-old',time()+28800]);$_COOKIE[Omnigo\PortalAccess::cookieName($config)]=$raw;
$admin=$security->user();$client=$db->one('SELECT * FROM users WHERE id=2');
$codes=[];$subjects=[];
