check(!$store->enabled($admin),'Kayıtlı hesap zorunlu açılmamalı');
denied(fn()=>$mfa->requestSetting($client,['password'=>$password,'enabled'=>true]),403);
denied(fn()=>$mfa->requestSetting($admin,['password'=>'wrong','enabled'=>true]),401);
