check($store->enabled($admin)&&$enabled['mfaEnabled']&&isset($enabled['csrf']),'Doğru kodla etkinleştir');
denied(fn()=>$security->user(),401);
check(!$db->one('SELECT token FROM sessions WHERE token=?',[$old]),'Eski oturum iptal');
denied(fn()=>$security->confirmMfa(['challenge'=>$pending['challenge'],'code'=>$code],$admin),401);
$resetBudget();$count=count($db->all('SELECT token FROM sessions'));
$pending=$security->login(['email'=>$admin['email'],'password'=>$password,'keepSession'=>true]);$code=$send();
check($pending['mfaRequired']&&!isset($pending['csrf'],$pending['user'])&&count($db->all('SELECT token FROM sessions'))===$count,'Parola tek başına tam oturum açmamalı');
$wrong=$code==='000000'?'000001':'000000';
for($i=0;$i<5;$i++)denied(fn()=>$security->confirmMfa(['challenge'=>$pending['challenge'],'code'=>$wrong]),401);
check((int)$db->one('SELECT attempts FROM admin_mfa_challenges')['attempts']===5,'Yanlış kod sayacı rollback olmamalı');
denied(fn()=>$security->confirmMfa(['challenge'=>$pending['challenge'],'code'=>$code]),401);
