$pending=$security->login(['email'=>$admin['email'],'password'=>$password]);$first=$send();
$db->run('UPDATE admin_mfa_challenges SET sent_at=0');$mfa->resend(['challenge'=>$pending['challenge']]);$second=$send();
if($first!==$second)denied(fn()=>$security->confirmMfa(['challenge'=>$pending['challenge'],'code'=>$first]),401);
$otherOrigin=new Security($db,[...$config,'origin'=>'https://different.example.test']);
denied(fn()=>$otherOrigin->confirmMfa(['challenge'=>$pending['challenge'],'code'=>$second]),401);
$result=$security->confirmMfa(['challenge'=>$pending['challenge'],'code'=>$second]);
check($result['user']['role']==='admin'&&count($db->all('SELECT token FROM sessions'))===$count+1,'İkinci faktör tam oturum açmalı');
check(count($db->all('SELECT token FROM admin_mfa_sessions'))===$count+1,'Doğrulanmış oturumlar işaretlenmeli');
denied(fn()=>$security->confirmMfa(['challenge'=>$pending['challenge'],'code'=>$second]),401);
$resetBudget();$pending=$security->login(['email'=>$admin['email'],'password'=>$password]);$code=$send();$db->run('UPDATE admin_mfa_challenges SET expires=?',[time()-1]);
denied(fn()=>$security->confirmMfa(['challenge'=>$pending['challenge'],'code'=>$code]),401);
$store->cancelChallenges(1);$resetBudget();
$pending=$security->login(['email'=>$admin['email'],'password'=>$password]);$code=$send();$db->run('UPDATE users SET password=? WHERE id=1',[Security::hashPassword('New-Test-Password-957!')]);
denied(fn()=>$security->confirmMfa(['challenge'=>$pending['challenge'],'code'=>$code]),401);
check($store->enabled($admin),'Parola değişimi MFA kapatmamalı');$db->run('UPDATE users SET password=? WHERE id=1',[$hash]);
$clientSecurity=new Security($db,[...$config,'portal_role'=>'client']);
check($clientSecurity->login(['email'=>$client['email'],'password'=>$password])['user']['role']==='client','Müşteri girişi korunmalı');
denied(fn()=>(new AdminMfaRoutes($db,$config,$security))->handle('/api/account/security','GET',$client),403);
$store->cancelChallenges(1);$resetBudget();
$pending=$security->login(['email'=>$admin['email'],'password'=>$password]);
$mail->runOne(fn()=>false);check($db->one("SELECT state,next_run FROM mail_outbox WHERE state='pending'")['next_run']>time(),'E-posta hatasında retry');
$db->run("UPDATE mail_outbox SET next_run=0 WHERE state='pending'");$code=$send();$security->confirmMfa(['challenge'=>$pending['challenge'],'code'=>$code]);
$key=random_bytes(32);$archive=BackupArchive::create($db,$key);$target=fresh();BackupArchive::restore($target,$archive,$key);
check((new AdminMfaStore($target,$config))->enabled($admin),'Yedek dönüşü MFA korunmalı');
check(!$target->all('SELECT * FROM admin_mfa_challenges')&&!$target->all('SELECT * FROM admin_mfa_sessions'),'Yedek eski kod ve oturum açmamalı');
