check($store->enabled($actor),'Kapatma kodu doğrulanana kadar koruma sürmeli');
$result=$security->confirmMfa(['challenge'=>$pending['challenge'],'code'=>$code],$actor);
check(!$store->enabled($actor)&&!$result['mfaEnabled']&&count($db->all('SELECT token FROM sessions WHERE user_id=1'))===1,'Kapatmada doğrulama ve oturum yenileme');
echo "Yönetici e-posta doğrulaması: kurulum, parola/kod ayrımı, süre/deneme, tek kullanım, yeniden gönderme, köken/rol, oturum iptali, posta retry ve yedek dönüşü geçti.\n";
